/* 画面の一番上で下に引っ張ると再読み込み（入力中の画面では動かない） */
(function(){const pr=document.createElement('div');pr.id='ptr';pr.textContent='↓ 引っ張って更新';document.body.appendChild(pr);let y0=null,dy=0,busy=false;const TH=70,hide=()=>pr.style.transform='translate(-50%,-80px)';
  document.addEventListener('touchstart',e=>{if(busy||S.tab==='edit'||window.scrollY>0||e.touches.length!==1){y0=null;return}y0=e.touches[0].clientY;dy=0},{passive:true});
  document.addEventListener('touchmove',e=>{if(y0==null)return;dy=e.touches[0].clientY-y0;if(dy<=0){hide();return}const d=Math.min(dy*0.5,100);pr.style.transform='translate(-50%,'+(d-60)+'px)';pr.textContent=dy*0.5>TH?'↻ 離すと更新':'↓ 引っ張って更新'},{passive:true});
  document.addEventListener('touchend',async()=>{if(y0==null)return;const go=dy*0.5>TH;y0=null;if(!go){hide();return}busy=true;pr.textContent='更新中…';pr.style.transform='translate(-50%,10px)';
    try{Object.assign(S,await run('api_init'));if(S.tab!=='edit')render();toast('最新の状態にしました')}catch(x){toast('更新できませんでした')}busy=false;hide()});})();
